  function renderNetworkTask(t,sequence,taskId){if(sequence!==networkTaskSequence)return;lastNetworkTask=t;el('extNetworkProgressFill').style.width=t.progress+'%';el('extNetworkProgressPercent').textContent=t.progress+'%';el('extNetworkProgressLabel').textContent=t.status==='completed'?i18nText('status.completed'):(t.status==='failed'?i18nText('status.needs_attention'):(t.status==='needs_action'?i18nText('status.needs_action'):i18nText('status.processing')));el('extNetworkTimeline').innerHTML=t.steps.map(function(s){return '<li class="'+s.status+'">'+extensionStepLabel(s)+' · '+extensionStatusLabel(s.status)+'</li>'}).join('');el('extNetworkLogs').textContent=t.logs.map(function(x){return '['+x.time+'] '+x.message}).join('\n');var current=t.steps.find(function(s){return s.status==='running'});if(current){el('extRemoteNetworkState').textContent=extensionStepLabel(current);el('extRemoteNetworkDetail').textContent=i18nText('extensions.processing_note')}if(t.status==='completed'){clearInterval(networkPoll);networkConnectInFlight=false;setNetworkControlsLocked(false);clearSessionCredentials();el('extNetworkConnectBtn').disabled=!backendOnline;el('extNetworkRecovery').classList.add('hidden');el('extSuccessBanner').classList.remove('hidden');el('extensionOverallStatus').textContent=i18nText('extensions.network_connected');el('extRemoteNetworkState').textContent=i18nText('extensions.connected');el('extRemoteNetworkDetail').textContent=i18nText('extensions.network_saved');var r=t.result||{};setCheck('local',true,r.local_address||i18nText('extensions.connected'));setCheck('peer',r.peer_reachable===true,r.peer_reachable?i18nText('extensions.reachable_prefix')+(r.remote_address||''):i18nText('extensions.not_reachable'));setCheck('genbox',r.genbox_reachable===true,r.genbox_reachable?i18nText('extensions.vps_can_access'):i18nText('extensions.cannot_access'));setCheck('url',!!r.genbox_url,r.genbox_url||i18nText('extensions.not_generated'));message(i18nText('extensions.network_complete'));extensionNext(5)}if(t.status==='failed'||t.status==='needs_action'){clearInterval(networkPoll);networkConnectInFlight=false;setNetworkControlsLocked(false);el('extSuccessBanner').classList.add('hidden');el('extNetworkConnectBtn').disabled=!backendOnline;var phase=extensionStepLabel({id:t.failed_phase||t.phase}),recovery=networkRecoveryText(t),recoveryButton=el('extNetworkRecoveryBtn');if(t.next_action&&t.next_action.type==='provide_secret')extensionNetworkModeChanged('auto');el('extNetworkRecovery').classList.remove('hidden');el('extNetworkRecoveryDetail').textContent=(t.status==='needs_action'?i18nText('status.needs_action')+'：':i18nText('extensions.failed_phase_prefix')+phase+'。')+recovery;el('extNetworkDiagnosticDetail').textContent=networkDiagnosticText(t.diagnostics);if(recoveryButton)recoveryButton.classList.add('hidden');el('extRemoteNetworkState').textContent=t.status==='needs_action'?i18nText('status.needs_action'):phase;el('extRemoteNetworkDetail').textContent=recovery;message(t.status==='needs_action'?i18nText('extensions.network_waiting_user'):i18nText('extensions.network_failed_plain'),t.status==='failed')}updateNoviceGuide()}
  window.extensionRetryNetworkCheck=function(){var creds=credential();if(!creds.password&&!creds.private_key){message(i18nText('extensions.retry_credential_help'),true);extensionNext(1);return}if(lastNetworkTask&&['TAILSCALE_NOT_INSTALLED','TAILSCALE_AUTH_KEY_REQUIRED','TAILSCALE_AUTH_REJECTED'].indexOf(lastNetworkTask.recovery_code)>=0&&!el('extNetworkToken').value.trim()){focusNetworkAuthKey();return}el('extNetworkRecovery').classList.add('hidden');extensionConnectNetwork()};
  window.extensionConnectNetwork=async function(){if(networkConnectInFlight||!requireDeploymentTarget()||!requireCredential())return;if(!trustedHostKey){message(i18nText('extensions.host_key_required_here'),true);renderNetworkHostKey();return}var mode=el('extRemoteNetworkMode').value||'auto',token=mode==='auto'?el('extNetworkToken').value.trim():'',snapshot=networkRequestContext(mode),taskCreated=false,sequence=++networkTaskSequence;networkConnectInFlight=true;lastNetworkTask=null;setNetworkControlsLocked(true);el('extNetworkConnectBtn').disabled=true;updateNoviceGuide();try{var body={target:target(),credential:credential(),trust_host_key:true,expected_host_key:trustedHostKey,provider:'tailscale',enrollment_token:token,operation_mode:mode,device_name:el('extDeviceName').value.trim(),management_url:''};var data=await json(await _authFetch('/api/extensions/network/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}));if(sequence!==networkTaskSequence)return;if(!networkContextMatches(snapshot,mode)){discardStaleNetworkView(sequence);return}taskCreated=true;if(token)el('extNetworkToken').value='';networkPoll=setInterval(async function(){try{var task=await json(await _authFetch('/api/extensions/network/tasks/'+data.task_id));if(sequence!==networkTaskSequence)return;if(!networkContextMatches(snapshot,mode)){discardStaleNetworkView(sequence);return}renderNetworkTask(task,sequence,data.task_id)}catch(e){if(sequence!==networkTaskSequence)return;clearInterval(networkPoll);networkConnectInFlight=false;setNetworkControlsLocked(false);el('extNetworkConnectBtn').disabled=!backendOnline;message(extensionError(e),true);updateNoviceGuide()}},800)}catch(e){if(sequence===networkTaskSequence)message(extensionError(e),true)}finally{if(sequence===networkTaskSequence&&!taskCreated){networkConnectInFlight=false;setNetworkControlsLocked(false);renderNetworkHostKey();updateNoviceGuide()}}};
  function renderLocalTailscale(s){localTailscale=s;var state=!s.installed?i18nText('extensions.not_installed'):(s.online?i18nText('extensions.connected'):i18nText('extensions.waiting_login'));var action=el('extLocalActionStatus');el('extLocalTailscaleState').textContent=state;el('extLocalTailscaleDetail').textContent=s.online?i18nText('extensions.tool_connected'):i18nText('extensions.login_same_tailnet');el('extLocalAppPort').textContent='http://localhost:'+(s.app_port||8892);el('extLocalServePort').textContent=(s.serve?i18nText('extensions.enabled_prefix'):i18nText('extensions.planned_prefix'))+(s.serve_port||8893);el('extLocalInstallBtn').disabled=!backendOnline||!!s.installed;el('extLocalLoginBtn').disabled=!backendOnline||!s.installed||!!s.online;el('extLocalServeBtn').disabled=!backendOnline||!s.online||!!s.serve;action.className='extension-action-status '+(s.serve?'success':(s.online?'pending':'failed'));action.textContent=s.serve?i18nText('extensions.private_entry_enabled'):(s.online?i18nText('extensions.enable_entry_next'):(!s.installed?i18nText('extensions.install_first'):i18nText('extensions.login_first')));setCheck('local',s.online,state);if(typeof updateNoviceGuide==='function')updateNoviceGuide()}
  window.extensionCheckLocalTailscale=async function(){try{renderLocalTailscale(await json(await _authFetch('/api/extensions/network/local/tailscale/status')))}catch(e){message(i18nText('extensions.local_check_failed')+extensionError(e),true)}};
  window.extensionInstallLocalTailscale=async function(){if(!backendOnline){message(i18nText('runtime.offline_detail'),true);return}try{var data=await json(await _authFetch('/api/extensions/network/local/tailscale/install',{method:'POST'}));message(i18nText('extensions.installing_tailscale'));localInstallPoll=setInterval(async function(){try{var task=await json(await _authFetch('/api/extensions/network/local/tailscale/install/'+data.task_id));if(task.status==='completed'){clearInterval(localInstallPoll);message(i18nText('extensions.tailscale_installed'));extensionCheckLocalTailscale()}else if(task.status==='failed'){clearInterval(localInstallPoll);message(task.error||i18nText('extensions.install_failed'),true)}}catch(e){clearInterval(localInstallPoll);message(extensionError(e),true)}},1000)}catch(e){message(extensionError(e),true)}};
  window.extensionLoginLocalTailscale=async function(){if(!backendOnline){message(i18nText('runtime.offline_detail'),true);return}try{var data=await json(await _authFetch('/api/extensions/network/local/tailscale/login',{method:'POST'}));if(data.login_url)window.open(data.login_url,'_blank','noopener');message(data.online?i18nText('extensions.tailnet_signed_in'):i18nText('extensions.finish_login'));extensionCheckLocalTailscale()}catch(e){message(extensionError(e),true)}};
  window.extensionServeLocalGenBox=async function(){if(!backendOnline){message(i18nText('runtime.offline_detail'),true);return}try{var data=await json(await _authFetch('/api/extensions/network/local/tailscale/serve',{method:'POST'}));message(i18nText('extensions.private_entry_url_prefix')+data.url);setCheck('url',true,data.url);extensionCheckLocalTailscale()}catch(e){message(extensionError(e),true)}};
  window.extensionCopy=async function(id){var input=el(id);try{await navigator.clipboard.writeText(input.value);message(i18nText('common.copied'))}catch(e){input.select();document.execCommand('copy');message(i18nText('common.copied'))}};
  window.extensionTogglePassword=function(id,button){var input=el(id);if(!input||!button)return;var visible=input.type==='password';input.type=visible?'text':'password';button.textContent=visible?'🙈':'👁';button.setAttribute('aria-pressed',String(visible));var english=typeof getUiLanguage==='function'&&getUiLanguage()==='en';var label=visible?(english?'Hide password':'隐藏密码'):(english?'Show password':'显示密码');button.setAttribute('aria-label',label);button.title=label};
  window.extensionRevealKey=function(id){var input=el(id||'extAdminKey');input.type=input.type==='password'?'text':'password'};
  window.extensionResetAdminKey=async function(){if(!currentDeployment||!currentDeployment.instance){message(i18nText('extensions.no_managed_instance'),true);return}var creds=credential();if(!creds.password&&!creds.private_key){message(i18nText('extensions.reset_needs_owner'),true);extensionNext(1);return}if(!confirm(i18nText('extensions.reset_confirm_prefix')+currentDeployment.instance.id+i18nText('extensions.reset_confirm_suffix')))return;try{var body={...discoveryBody(),instance_id:currentDeployment.instance.id};var data=await json(await _authFetch('/api/extensions/instances/reset-admin-key',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}));el('extAdminKey').value=data.admin_key;el('extAdminKey').type='password';message(i18nText('extensions.reset_success_page'))}catch(e){message(i18nText('extensions.reset_failed_prefix')+extensionError(e),true)}};
  function startTaskPolling(taskId){clearInterval(taskPoll);taskPoll=setInterval(async function(){try{await renderTask(await json(await _authFetch('/api/extensions/tasks/'+taskId)),taskId,false)}catch(e){clearInterval(taskPoll);message(extensionError(e),true)}},800)}
  function selectRecoveredTask(summary){var taskId=summary.active_task_id||summary.latest_task_id;return {taskId:taskId,task:(summary.tasks||[]).find(function(item){return item.id===taskId})}}
  async function extensionRestoreTask(){var summary=await json(_authFetch('/api/extensions/tasks'));var selected=selectRecoveredTask(summary),taskId=selected.taskId,task=selected.task;if(summary.store_warning)message(summary.store_warning,true);if(!task)return;await renderTask(task,taskId,true);if(task.status==='interrupted'){clearInterval(taskPoll);message(i18nText('extensions.task_interrupted')+' '+extensionRecoveryText(task.recovery_action),true);return}if(task.status==='completed'&&task.result&&task.result.credential_recovery_required){message(extensionRecoveryText(task.recovery_action),true)}if(summary.active_task_id)startTaskPolling(taskId)}
